/**
 * Nepal administrative divisions and their centroids.
 *
 * Structure (names, types, ward counts, official websites) comes from
 * `data-de-nepal` (MIT), which mirrors the Local Government Resource
 * Management System listing of the Ministry of Local Government:
 *
 *   7 provinces
 *  77 districts
 * 753 local levels - 6 metropolitan cities, 11 sub-metropolitan cities,
 *   276 municipalities, 460 rural municipalities
 * 6,743 wards
 *
 * Coordinates come from the DDGN-coded high-resolution boundary polygons in
 * `nepal-geojson` (MIT). Each `lat`/`lng` is the area-weighted centroid of
 * the real boundary polygon, computed in `scripts/build-geo.mjs`.
 *
 * A centroid is a representative point for distance ranking only. It is never
 * a residential address and is never shown as one.
 *
 * Generated file - do not edit by hand. See README "Data and provenance".
 */

export type LocalType = 'metro' | 'submetro' | 'municipal' | 'rural';

export interface LocalLevel {
  /** Stable id from the source dataset. */
  id: number;
  name: string;
  nameNp: string;
  type: LocalType;
  typeNp: string;
  area: number;
  wards: number;
  /** Official website published by the local level. */
  site: string;
  /** Area-weighted centroid of the boundary. Null when not derivable. */
  lat: number | null;
  lng: number | null;
}

export interface District {
  id: number;
  name: string;
  nameNp: string;
  hq: string;
  hqNp: string;
  area: number;
  site: string;
  lat: number | null;
  lng: number | null;
  lg: LocalLevel[];
}

export interface Province {
  id: number;
  name: string;
  nameNp: string;
  code: string;
  hq: string;
  hqNp: string;
  area: number;
  site: string;
  lat: number;
  lng: number;
  districts: District[];
}

